#!/usr/bin/env python3
"""Measure climb batches' commits by category. Read-only on the repo."""
import subprocess, re, json, sys, os, collections

REPO = '/home/user/fortress'
OUT = os.path.dirname(os.path.abspath(__file__))


def git(*args, text=True):
    r = subprocess.run(['git', '-C', REPO] + list(args), capture_output=True)
    return r.stdout.decode('utf-8', 'replace') if text else r.stdout


BATCHES = {
    'b4': ['3f297441c', '57600bc27', 'b628871a2', '488b47934', 'ef1ff3ec5', 'b5acbe591', 'cb5bd2dd5'],
    'b5': ['e893a3e00', '3924e7ec3', '0b1881317', '601f52736', 'da53904cd', 'fe002948e', '396ee649f', '896bacc7d', 'ebc134652'],
    'b5D': ['ab914b6e0', '896fae47c', 'abe06a743', 'eb83706de'],
    'b5calc': ['eb2d7e1e6', '3b4a9312c', '69256f86a', '09d8dd4a1', '5b586fb2c'],
}
BASE = {'b4': '47437c65f', 'b5': '6030e4b36', 'b5D': 'eac768e00', 'b5calc': 'fbd4e0ab6'}

COORD = {
    'explorations/coordinator/FACTS.md', 'explorations/coordinator/POSITIONS.md',
    'explorations/coordinator/PLAN.md', 'explorations/coordinator/INDEX.md',
    'explorations/fortress-gap-ledger.md', 'explorations/microgpt-run-c-handover.md',
}
CAPT = {'.txt', '.tsv', '.out', '.log', '.csv', '.json'}
PROB = {'.fss', '.fsi', '.test'}
SCRI = {'.sh', '.py', '.js', '.java', '.mjs', '.bash', '.awk', '.pl', '.rb', '.scala', '.ts', '.sed'}
TESTDIRS = ('ProjectFortress/tests/', 'ProjectFortress/compiler_tests/', 'ProjectFortress/library_tests/',
            'ProjectFortress/not_passing_yet/', 'ProjectFortress/compiler_regressions/',
            'ProjectFortress/other_compiler_tests/', 'ProjectFortress/not_working_compiler_tests/',
            'ProjectFortress/linker_tests/', 'ProjectFortress/parser_tests/',
            'ProjectFortress/syntax_abstraction_tests/', 'ProjectFortress/static_tests/',
            'ProjectFortress/demos/', 'ProjectFortress/shelltests/')
BUILDFILES = ('build.xml', 'ProjectFortress/build.xml', 'ProjectFortress/ant', 'bin/')


def category(p):
    if p in COORD:
        return 'COORD'
    if p.startswith('explorations/'):
        ext = os.path.splitext(p)[1].lower()
        if ext == '.md':
            return 'REC_REPORTS'
        if ext in CAPT:
            return 'REC_CAPTURES'
        if ext in PROB:
            return 'REC_PROBES'
        if ext in SCRI:
            return 'REC_SCRIPTS'
        return 'REC_OTHER'
    if p.startswith('Library/') or p.startswith('ProjectFortress/LibraryBuiltin/'):
        return 'CODE_lib'
    if p.startswith('ProjectFortress/src/'):
        if re.search(r'JUTest\.java$|/tests/unit_tests/', p):
            return 'TESTS_junit'
        if p.endswith('.java'):
            if p.startswith('ProjectFortress/src/com/sun/fortress/nodes/'):
                return 'CODE_java_generated'
            return 'CODE_java'
        if p.endswith('.scala'):
            return 'CODE_scala'
        return 'CODE_other'
    if p.startswith('ProjectFortress/astgen/'):
        return 'CODE_astgen'
    if any(p == b or p.startswith(b) for b in BUILDFILES) or p.endswith('build.xml'):
        return 'CODE_build'
    if p.startswith('Specification/'):
        if p == 'Specification/fortress.pdf':
            return 'SPEC_pdf'
        if p.endswith('.tex'):
            return 'SPEC_tex'
        return 'SPEC_other'
    if p.startswith(TESTDIRS):
        return 'TESTS'
    return 'OTHER_TREE'


def commit_changes(c):
    """Return list of dicts: status, old, new, add, dele, dst_sha, binary."""
    raw = git('show', '--raw', '--numstat', '-M', '-z', '--no-abbrev', '--format=', c)
    toks = raw.split('\0')
    i = 0
    raws = []
    nums = []
    while i < len(toks):
        t = toks[i]
        if t == '':
            i += 1
            continue
        if t.startswith(':'):
            parts = t[1:].split()
            status = parts[4]
            if status[0] in 'RC':
                old, new = toks[i + 1], toks[i + 2]
                i += 3
            else:
                old = new = toks[i + 1]
                i += 2
            raws.append(dict(status=status[0], old=old, new=new, src_sha=parts[2], dst_sha=parts[3]))
        else:
            # numstat: "add\tdel\tpath" or "add\tdel\t" then old\0new\0
            t = t.lstrip('\n')
            a, d, rest = t.split('\t', 2)
            if rest == '':
                old, new = toks[i + 1], toks[i + 2]
                i += 3
            else:
                old = new = rest
                i += 1
            nums.append(dict(add=a, dele=d, old=old, new=new))
    assert len(raws) == len(nums), (c, len(raws), len(nums))
    out = []
    for r, n in zip(raws, nums):
        assert r['new'] == n['new'], (r, n)
        binary = n['add'] == '-'
        r.update(add=0 if binary else int(n['add']), dele=0 if binary else int(n['dele']), binary=binary)
        out.append(r)
    return out


def blob_size(sha):
    if set(sha) == {'0'}:
        return 0
    return int(git('cat-file', '-s', sha).strip() or 0)


def blob_lines(sha):
    if set(sha) == {'0'}:
        return 0
    return git('cat-file', '-p', sha, text=False).count(b'\n')


def main():
    result = {}
    head_files = set(git('ls-files').splitlines())
    per_batch_files = {}
    for b, commits in BATCHES.items():
        files = collections.OrderedDict()  # final path -> info
        cat_lines = collections.defaultdict(lambda: [0, 0])
        per_commit = []
        for c in commits:
            ch = commit_changes(c)
            ca = sum(x['add'] for x in ch)
            cd = sum(x['dele'] for x in ch)
            per_commit.append((c, len(ch), ca, cd))
            for x in ch:
                p = x['new']
                cat = category(p)
                cat_lines[cat][0] += x['add']
                cat_lines[cat][1] += x['dele']
                # track rename chains
                key = p
                if x['status'] == 'R' and x['old'] in files:
                    info = files.pop(x['old'])
                else:
                    info = files.get(key) or dict(path=p, first_status=x['status'], old=x['old'], statuses=[], add=0, dele=0,
                                                   binary=False, commits=[], add_sha=None)
                info['path'] = p
                info['statuses'].append(x['status'])
                info['add'] += x['add']
                info['dele'] += x['dele']
                info['binary'] |= x['binary']
                info['commits'].append(c)
                info['last_sha'] = x['dst_sha']
                if x['status'] == 'A':
                    info['add_sha'] = x['dst_sha']
                if x['status'] == 'R':
                    info['renamed_from'] = x['old']
                files[p] = info
        for p, info in files.items():
            info['cat'] = category(p)
            info['bytes'] = blob_size(info['last_sha'])
            info['final_lines'] = blob_lines(info['last_sha']) if not info['binary'] else None
            info['at_head'] = p in head_files
            if info['first_status'] == 'A' and set(info['last_sha']) == {'0'}:
                info['bytes_when_added'] = blob_size(info['add_sha']) if info['add_sha'] else 0
        per_batch_files[b] = files
        result[b] = dict(per_commit=per_commit, cat_lines={k: v for k, v in cat_lines.items()})
    json.dump({b: list(f.values()) for b, f in per_batch_files.items()}, open(os.path.join(OUT, 'files.json'), 'w'), indent=1)
    json.dump(result, open(os.path.join(OUT, 'cats.json'), 'w'), indent=1)
    for b in result:
        print('==', b)
        for pc in result[b]['per_commit']:
            print('  ', pc)
        for k, v in sorted(result[b]['cat_lines'].items()):
            n = sum(1 for f in per_batch_files[b].values() if f['cat'] == k)
            print('   %-20s files %4d  +%6d -%5d' % (k, n, v[0], v[1]))


if __name__ == '__main__':
    main()

