"""Citation check of batch record files against tracked .md files at HEAD; duplicates; tests."""
import subprocess, re, json, os, collections

REPO = '/home/user/fortress'
OUT = os.path.dirname(os.path.abspath(__file__))
F = json.load(open(os.path.join(OUT, 'files.json')))


def git(*args, text=True):
    r = subprocess.run(['git', '-C', REPO] + list(args), capture_output=True)
    return r.stdout.decode('utf-8', 'replace') if text else r.stdout


head_files = git('ls-files').splitlines()
head_set = set(head_files)
md_files = [p for p in head_files if p.endswith('.md')]

# basename multiplicity across HEAD-tracked files plus every batch file
all_paths = set(head_files)
for b in F:
    for f in F[b]:
        all_paths.add(f['path'])
base_count = collections.Counter(os.path.basename(p) for p in all_paths)
COMMON = {'README.md', 'REPORT.md', 'record.md', 'RECORD.md', 'SKEPTIC.md', 'JUDGE.md', 'NOTE.md'}


def needle_for(p):
    """Shortest '/'-suffix of p that is unique among all paths (basename if unique)."""
    parts = p.split('/')
    for k in range(1, len(parts) + 1):
        suf = '/'.join(parts[-k:])
        if k == 1 and parts[-1] in COMMON:
            continue
        n = sum(1 for q in all_paths if q == suf or q.endswith('/' + suf))
        if n <= 1:
            return suf
    return p


# Precompute needles; to keep it fast, index all_paths by basename
by_base = collections.defaultdict(list)
for q in all_paths:
    by_base[os.path.basename(q)].append(q)


def needle_fast(p):
    parts = p.split('/')
    cands = by_base[parts[-1]]
    for k in range(1, len(parts) + 1):
        suf = '/'.join(parts[-k:])
        if k == 1 and parts[-1] in COMMON:
            continue
        n = sum(1 for q in cands if q == suf or q.endswith('/' + suf))
        if n <= 1:
            return suf
    return p


needles = {}   # path -> needle
dirneedles = {}  # path -> needle of parent dir
stems = {}
for b in F:
    for f in F[b]:
        if f['cat'].startswith('REC'):
            p = f['path']
            needles[p] = needle_fast(p)
            d = os.path.dirname(p)
            dparts = d.split('/')
            # shortest unique dir suffix among dirs of all paths
            dirneedles[p] = None
            alldirs_c = None
            stems[p] = os.path.basename(p).split('.')[0]

alldirs = set()
for q in all_paths:
    d = os.path.dirname(q)
    while d:
        alldirs.add(d)
        d = os.path.dirname(d)
dir_by_base = collections.defaultdict(list)
for d in alldirs:
    dir_by_base[os.path.basename(d)].append(d)


def dir_needle(d):
    parts = d.split('/')
    cands = dir_by_base[parts[-1]]
    for k in range(1, len(parts) + 1):
        suf = '/'.join(parts[-k:])
        n = sum(1 for q in cands if q == suf or q.endswith('/' + suf))
        if n <= 1:
            return suf
    return d


for p in needles:
    dirneedles[p] = dir_needle(os.path.dirname(p))

needle_set = set(needles.values())
dir_set = set(dirneedles.values())
stem_set = set(s for s in stems.values() if len(s) >= 5)

